'use client';

import { useState } from 'react';

import {
  useAutoplay,
  type AutoplayStep,
} from '@/registry/ndeko/hooks/use-autoplay';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button, type ButtonProps } from '@/registry/ndeko/ui/button';

import { GLYPHS, type LivingIconName } from './_parts/living-glyphs';
import { useHover } from './_parts/use-hover';
import { usePose, type Pose } from './_parts/use-pose';

export type LivingTone =
  'secondary' | 'outline' | 'destructive' | 'info' | 'success' | 'warning';

type ToneRecipe = {
  variant: ButtonProps['variant'];
  className?: string;
};

const TONES: Record<LivingTone, ToneRecipe> = {
  secondary: { variant: 'secondary' },
  outline: { variant: 'outline' },
  destructive: { variant: 'destructive' },
  info: {
    variant: 'secondary',
    className: 'bg-info/10 text-info-foreground hover:bg-info/15',
  },
  success: {
    variant: 'secondary',
    className: 'bg-success/10 text-success-foreground hover:bg-success/15',
  },
  warning: {
    variant: 'secondary',
    className: 'bg-warning/10 text-warning-foreground hover:bg-warning/15',
  },
};

/** A demonstration presses deeper than a finger does, so the press reads from across the page. */
const DEMO_PRESSED = 'scale-[0.94]';

function demoPressOf(forcedPose: Pose | undefined) {
  if (forcedPose === 'press') {
    return DEMO_PRESSED;
  }
  return undefined;
}

export type LivingButtonProps = Omit<ButtonProps, 'variant'> & {
  /** The icon that answers the hand: the arrow leaves and returns, the bin lifts its lid, the bell swings once, the download drops. */
  icon: LivingIconName;
  tone?: LivingTone;
  /** Holds the icon in a pose, for a demonstration that plays it without a pointer. */
  pose?: Pose;
};

/**
 * A button whose icon acts out its verb when the hand reaches it and when it is pressed, once and
 * never in a loop. The keyboard gets the same answers as the pointer. The arrow follows the label;
 * the other icons come before it. Under reduced motion the arrow and the bell keep still, and the
 * bin and the download change pose without travelling there.
 */
export function LivingButton({
  icon,
  tone = 'secondary',
  pose: forcedPose,
  className,
  children,
  ...props
}: LivingButtonProps) {
  const { pose: livePose, poseHandlers } = usePose<HTMLSpanElement>();
  const shownPose = forcedPose ?? livePose;
  const recipe = TONES[tone];
  const Glyph = GLYPHS[icon];
  const followsLabel = icon === 'arrow';

  return (
    <span className='contents' {...poseHandlers}>
      <Button
        variant={recipe.variant}
        className={cn(recipe.className, demoPressOf(forcedPose), className)}
        {...props}
      >
        {!followsLabel && <Glyph pose={shownPose} />}
        {children}
        {followsLabel && <Glyph pose={shownPose} />}
      </Button>
    </span>
  );
}

type DemoButton = 'continue' | 'download' | 'delete' | 'remind';

type Forced = {
  button: DemoButton;
  pose: Pose;
};

type DemoBeat = Forced & {
  after: number;
};

type ButtonSpec = {
  id: DemoButton;
  icon: LivingIconName;
  tone: LivingTone;
  label: string;
};

const BUTTONS: ButtonSpec[] = [
  { id: 'continue', icon: 'arrow', tone: 'secondary', label: 'Continue' },
  { id: 'download', icon: 'download', tone: 'outline', label: 'Download' },
  { id: 'delete', icon: 'bin', tone: 'destructive', label: 'Delete' },
  { id: 'remind', icon: 'bell', tone: 'info', label: 'Remind me' },
];

/** Each button is reached, pressed and let go in turn. The bin is reached again after the press, as a hand that stays on it would. */
const BEATS: DemoBeat[] = [
  { after: 1100, button: 'continue', pose: 'hover' },
  { after: 1200, button: 'continue', pose: 'press' },
  { after: 380, button: 'continue', pose: 'rest' },
  { after: 700, button: 'download', pose: 'hover' },
  { after: 1100, button: 'download', pose: 'press' },
  { after: 380, button: 'download', pose: 'rest' },
  { after: 700, button: 'delete', pose: 'hover' },
  { after: 1300, button: 'delete', pose: 'press' },
  { after: 420, button: 'delete', pose: 'hover' },
  { after: 700, button: 'delete', pose: 'rest' },
  { after: 700, button: 'remind', pose: 'hover' },
  { after: 1300, button: 'remind', pose: 'press' },
  { after: 700, button: 'remind', pose: 'rest' },
];

function forcedWhile(isAutoplaying: boolean, forced: Forced | null) {
  if (isAutoplaying) {
    return forced;
  }
  return null;
}

function poseOfButton(forced: Forced | null, id: DemoButton) {
  if (forced === null) {
    return undefined;
  }
  if (forced.button !== id) {
    return undefined;
  }
  return forced.pose;
}

export default function Button66() {
  const [forced, setForced] = useState<Forced | null>(null);
  const { isHovered, hoverHandlers } = useHover();
  const steps: AutoplayStep[] = BEATS.map((beat) => ({
    after: beat.after,
    run: () => setForced({ button: beat.button, pose: beat.pose }),
  }));
  const { ref, isAutoplaying } = useAutoplay(steps, {
    loopAfter: 1500,
    onReset: () => setForced(null),
    isEnabled: !isHovered,
  });
  const shown = forcedWhile(isAutoplaying, forced);

  return (
    <div
      ref={ref}
      className='@container w-full max-w-[34rem]'
      {...hoverHandlers}
    >
      <div className='grid grid-cols-2 justify-items-center gap-3 @lg:flex @lg:flex-wrap @lg:justify-center'>
        {BUTTONS.map((spec) => (
          <LivingButton
            key={spec.id}
            icon={spec.icon}
            tone={spec.tone}
            pose={poseOfButton(shown, spec.id)}
          >
            {spec.label}
          </LivingButton>
        ))}
      </div>
    </div>
  );
}

'use client';

import { useEffect, useRef } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ArrowRightIcon, BellIcon } from '@/registry/ndeko/lib/icons';

import type { Pose } from './use-pose';

export type LivingIconName = 'arrow' | 'download' | 'bin' | 'bell';

export type GlyphProps = {
  pose: Pose;
};

type Act = {
  keyframes: Keyframe[];
  options: KeyframeAnimationOptions;
};

type Acts = {
  hover: Act;
  press: Act;
};

const OUT_STRONG = 'cubic-bezier(0.23, 1, 0.32, 1)';

const IN_OUT_STRONG = 'cubic-bezier(0.77, 0, 0.175, 1)';

const SWING_OFFSETS = [0, 0.16, 0.42, 0.64, 0.82, 1];

const SWING_REACH = [0, 1, -0.75, 0.45, -0.2, 0];

/** The bell hangs from its top, a little below the top of its box. */
const BELL_HINGE = '50% 8%';

/** The lid turns about its left end, which is where the bin's hinge would be. */
const LID_HINGE = '4px 7.5px';

const POSE_MOTION =
  'transition-transform duration-200 ease-(--ease-out-strong)';

/** The arrow leaves through the right edge of its slot and comes back from the left edge, with a short beat of an empty slot between. */
const ARROW_ROLL: Keyframe[] = [
  {
    offset: 0,
    transform: 'translateX(0%)',
    opacity: 1,
    easing: IN_OUT_STRONG,
  },
  { offset: 0.4, transform: 'translateX(130%)', opacity: 0 },
  {
    offset: 0.46,
    transform: 'translateX(-130%)',
    opacity: 0,
    easing: OUT_STRONG,
  },
  { offset: 1, transform: 'translateX(0%)', opacity: 1 },
];

const ARROW_POKE: Keyframe[] = [
  { offset: 0, transform: 'translateX(0px)' },
  { offset: 0.4, transform: 'translateX(2.5px)' },
  { offset: 1, transform: 'translateX(0px)' },
];

function swingKeyframesOf(amplitude: number): Keyframe[] {
  return SWING_OFFSETS.map((offset, step) => {
    const angle = amplitude * SWING_REACH[step];
    return { offset, transform: `rotate(${angle}deg)`, easing: 'ease-in-out' };
  });
}

const ARROW_ACTS: Acts = {
  hover: { keyframes: ARROW_ROLL, options: { duration: 560 } },
  press: {
    keyframes: ARROW_POKE,
    options: { duration: 280, easing: OUT_STRONG },
  },
};

const BELL_ACTS: Acts = {
  hover: { keyframes: swingKeyframesOf(14), options: { duration: 800 } },
  press: { keyframes: swingKeyframesOf(20), options: { duration: 520 } },
};

const ARROW_DROP: Record<Pose, string> = {
  rest: 'translateY(0px)',
  hover: 'translateY(2.4px)',
  press: 'translateY(3.6px)',
};

const LID_TURN: Record<Pose, string> = {
  rest: 'translateY(0px) rotate(0deg)',
  hover: 'translateY(-1.5px) rotate(-12deg)',
  press: 'translateY(0.9px) rotate(0deg)',
};

/**
 * Plays an act on the element it returns when the pose changes: the hover act when a control is
 * reached from rest, the press act whenever it is pressed. Nothing plays under reduced motion.
 */
function useActs<Element extends HTMLElement>(pose: Pose, acts: Acts) {
  const ref = useRef<Element>(null);
  const before = useRef<Pose>('rest');
  const isStill = usePrefersReducedMotion();

  useEffect(() => {
    const previous = before.current;
    before.current = pose;
    const element = ref.current;
    const hasChanged = previous !== pose;
    if (!element) {
      return;
    }
    if (!hasChanged || isStill) {
      return;
    }
    if (pose === 'press') {
      element.animate(acts.press.keyframes, acts.press.options);
      return;
    }
    const startsHover = pose === 'hover' && previous === 'rest';
    if (startsHover) {
      element.animate(acts.hover.keyframes, acts.hover.options);
    }
  }, [pose, acts, isStill]);

  return ref;
}

function ArrowGlyph({ pose }: GlyphProps) {
  const ref = useActs<HTMLSpanElement>(pose, ARROW_ACTS);

  return (
    <span
      aria-hidden='true'
      className='flex size-4 shrink-0 items-center justify-center overflow-hidden'
    >
      <span ref={ref} className='flex'>
        <ArrowRightIcon />
      </span>
    </span>
  );
}

function BellGlyph({ pose }: GlyphProps) {
  const ref = useActs<HTMLSpanElement>(pose, BELL_ACTS);

  return (
    <span
      ref={ref}
      aria-hidden='true'
      style={{ transformOrigin: BELL_HINGE }}
      className='flex shrink-0'
    >
      <BellIcon />
    </span>
  );
}

/** The module's tray and arrow cannot move apart, so this one draws them as two parts on the same grid and stroke. */
function DownloadGlyph({ pose }: GlyphProps) {
  return (
    <svg
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth={1.75}
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
      className='size-4'
    >
      <g style={{ transform: ARROW_DROP[pose] }} className={POSE_MOTION}>
        <path d='M12 3.5v11' />
        <path d='m7.5 10 4.5 4.5 4.5-4.5' />
      </g>
      <path d='M4.5 15.5v2.2a2.3 2.3 0 0 0 2.3 2.3h10.4a2.3 2.3 0 0 0 2.3-2.3v-2.2' />
    </svg>
  );
}

/** The module's bin draws its lid and its body as one shape, so the lid cannot lift; this one draws them apart. */
function BinGlyph({ pose }: GlyphProps) {
  return (
    <svg
      viewBox='0 0 24 24'
      fill='none'
      stroke='currentColor'
      strokeWidth={1.75}
      strokeLinecap='round'
      strokeLinejoin='round'
      aria-hidden='true'
      className='size-4'
    >
      <g
        style={{ transform: LID_TURN[pose], transformOrigin: LID_HINGE }}
        className={POSE_MOTION}
      >
        <path d='M4 7.5h16' />
        <path d='M9.5 7.5V6.1A1.1 1.1 0 0 1 10.6 5h2.8a1.1 1.1 0 0 1 1.1 1.1v1.4' />
      </g>
      <path d='M6 7.5l.85 11.1a2 2 0 0 0 2 1.9h6.3a2 2 0 0 0 2-1.9L18 7.5' />
      <path d='M10.2 11.5v5M13.8 11.5v5' />
    </svg>
  );
}

export const GLYPHS: Record<LivingIconName, React.ComponentType<GlyphProps>> = {
  arrow: ArrowGlyph,
  download: DownloadGlyph,
  bin: BinGlyph,
  bell: BellGlyph,
};

'use client';

import { useState } from 'react';

/** Whether a mouse or a pen rests on an element. A finger does not hover, so a touch never counts. */
export function useHover() {
  const [isHovered, setIsHovered] = useState(false);

  function hoverStarts(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType !== 'touch') {
      setIsHovered(true);
    }
  }

  function hoverEnds() {
    setIsHovered(false);
  }

  const hoverHandlers = {
    onPointerEnter: hoverStarts,
    onPointerLeave: hoverEnds,
  };

  return { isHovered, hoverHandlers };
}

'use client';

import { useState } from 'react';

export type Pose = 'rest' | 'hover' | 'press';

const PRESS_KEYS = [' ', 'Enter'];

function poseOf(isPressed: boolean, isReached: boolean): Pose {
  if (isPressed) {
    return 'press';
  }
  if (isReached) {
    return 'hover';
  }
  return 'rest';
}

function isPressKey(key: string) {
  return PRESS_KEYS.includes(key);
}

/**
 * What a control is being offered. A mouse or a pen on it, or the keyboard on it, is a hover; a
 * press of the pointer or of Space or Enter is a press. A finger never hovers, so a touch only
 * presses. Spread the handlers on an ancestor of the control: the events reach it from inside.
 */
export function usePose<Element extends HTMLElement>() {
  const [isHovered, setIsHovered] = useState(false);
  const [isFocused, setIsFocused] = useState(false);
  const [isPressed, setIsPressed] = useState(false);
  const isReached = isHovered || isFocused;
  const pose = poseOf(isPressed, isReached);

  function hoverStarts(event: React.PointerEvent<Element>) {
    if (event.pointerType !== 'touch') {
      setIsHovered(true);
    }
  }

  function hoverEnds() {
    setIsHovered(false);
    setIsPressed(false);
  }

  function pointerPresses() {
    setIsPressed(true);
  }

  function pointerReleases() {
    setIsPressed(false);
  }

  function focusStarts(event: React.FocusEvent<Element>) {
    const isKeyboardFocus = event.target.matches(':focus-visible');
    if (isKeyboardFocus) {
      setIsFocused(true);
    }
  }

  function focusEnds() {
    setIsFocused(false);
    setIsPressed(false);
  }

  function keyPresses(event: React.KeyboardEvent<Element>) {
    if (isPressKey(event.key)) {
      setIsPressed(true);
    }
  }

  function keyReleases(event: React.KeyboardEvent<Element>) {
    if (isPressKey(event.key)) {
      setIsPressed(false);
    }
  }

  const poseHandlers = {
    onPointerEnter: hoverStarts,
    onPointerLeave: hoverEnds,
    onPointerDown: pointerPresses,
    onPointerUp: pointerReleases,
    onPointerCancel: pointerReleases,
    onFocus: focusStarts,
    onBlur: focusEnds,
    onKeyDown: keyPresses,
    onKeyUp: keyReleases,
  };

  return { pose, poseHandlers };
}
